import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.BLV0JUXI.js";const b=JSON.parse('{"title":"企业级场景清单与选型结论（阶段一交付）","description":"","frontmatter":{},"headers":[],"relativePath":"ecommerce-mini-program/docs/scenarios.md","filePath":"ecommerce-mini-program/docs/scenarios.md","lastUpdated":1793854502000}'),c={name:"ecommerce-mini-program/docs/scenarios.md"};function a(s,t,h,n,i,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="企业级场景清单与选型结论-阶段一交付" tabindex="-1">企业级场景清单与选型结论（阶段一交付） <a class="header-anchor" href="#企业级场景清单与选型结论-阶段一交付" aria-label="Permalink to &quot;企业级场景清单与选型结论（阶段一交付）&quot;">​</a></h1><blockquote><p>要求：至少落地 8 个。本清单共 12 个，全部给出「业务背景 → 方案对比 → 选型结论 → 实现位置 → 验证方式」。 具体代码在阶段二～四实现，本阶段只锁定方案，避免返工。</p></blockquote><h2 id="场景-1-登录态与路由守卫" tabindex="-1">场景 1：登录态与路由守卫 <a class="header-anchor" href="#场景-1-登录态与路由守卫" aria-label="Permalink to &quot;场景 1：登录态与路由守卫&quot;">​</a></h2><p><strong>业务背景</strong>：六端静默登录能力不同，订单/地址/售后需要登录；登录后要回到原页面，token 过期要静默续期，401/403 要统一拦截。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 每页 <code>onShow</code> 自行判断</td><td>每个页面复制登录判断与跳转</td><td>实现快</td><td>重复代码、遗漏风险高、无法统一续期</td></tr><tr><td>B. 登录 Provider + 路由守卫</td><td><code>LoginProvider</code> 统一各端票据，拦截器统一 401/403，白名单 + 回跳参数</td><td>一处治理、可测试、六端一致</td><td>需要设计守卫与页面栈回跳协议</td></tr></tbody></table><p><strong>选型：B。</strong> 实现位置：<code>providers/login/</code>、<code>platform/login.ts</code>、<code>utils/route-guard.ts</code>、<code>api/core</code> 拦截器。验证：未登录进入订单页 → 跳登录 → 登录成功回原页；token 过期 → 自动续期一次 → 仍失败才跳登录。</p><h2 id="场景-2-列表分页抽象" tabindex="-1">场景 2：列表分页抽象 <a class="header-anchor" href="#场景-2-列表分页抽象" aria-label="Permalink to &quot;场景 2：列表分页抽象&quot;">​</a></h2><p><strong>业务背景</strong>：首页瀑布流、分类列表、搜索、订单列表都需分页；快速切 Tab 会产生重复请求与错序数据。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 各页面自行维护 page/loading</td><td>每页复制分页逻辑</td><td>无抽象成本</td><td>状态分散，竞态治理困难</td></tr><tr><td>B. <code>usePagination</code> 组合式函数</td><td>统一 <code>loading/finished/error/reset/loadMore</code>，内部用请求序号丢弃过期响应</td><td>行为一致、易测</td><td>需要约定 request 签名与错误处理</td></tr></tbody></table><p><strong>选型：B。</strong> 实现位置：<code>composables/usePagination.ts</code>（阶段二）。验证：连续快速切换分类 Tab，旧分类响应不覆盖新分类列表；下拉刷新重置页码。</p><h2 id="场景-3-请求竞态与取消" tabindex="-1">场景 3：请求竞态与取消 <a class="header-anchor" href="#场景-3-请求竞态与取消" aria-label="Permalink to &quot;场景 3：请求竞态与取消&quot;">​</a></h2><p><strong>业务背景</strong>：搜索联想、筛选切换会并发请求；只丢弃响应仍会浪费流量，小程序还需要真正中止请求。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 只做响应打标丢弃</td><td>axios/请求层加序号</td><td>实现简单</td><td>请求仍占用连接与配额</td></tr><tr><td>B. 真取消 + 响应丢弃</td><td>小程序 <code>RequestTask.abort</code>，H5 <code>AbortController</code>，平台层统一</td><td>省流量、状态干净</td><td>需要平台适配与取消错误码归一</td></tr></tbody></table><p><strong>选型：B。</strong> 实现位置：<code>platform/request.ts</code>、<code>api/core</code>。验证：输入关键词连续触发 5 次请求，仅最后一次生效，控制台可见前 4 次 aborted；取消不产生错误提示。</p><h2 id="场景-4-购物车数据一致性" tabindex="-1">场景 4：购物车数据一致性 <a class="header-anchor" href="#场景-4-购物车数据一致性" aria-label="Permalink to &quot;场景 4：购物车数据一致性&quot;">​</a></h2><p><strong>业务背景</strong>：详情页加购、购物车增减、结算回退都会修改购物车；弱网下需要即时反馈又不能丢数据。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 每次操作后全量刷新</td><td>服务端为准，重新拉列表</td><td>一致性强</td><td>弱网卡顿、数量闪烁、体验差</td></tr><tr><td>B. 本地乐观更新 + 失败回滚</td><td>先改本地快照，请求失败回滚并提示；跨页事件同步</td><td>响应快、体验好</td><td>需要版本号/快照与冲突处理</td></tr></tbody></table><p><strong>选型：B。</strong> 同 SKU 合并加购；购物车 store 维护 <code>snapshotVersion</code>，写入成功才更新基准快照。实现位置：<code>stores/cart.ts</code>、<code>api/cart.ts</code>。验证：飞行模式下加购 → 数量先 +1 → 失败回滚 + Toast；恢复网络后数据一致。</p><h2 id="场景-5-sku-规格选择器" tabindex="-1">场景 5：SKU 规格选择器 <a class="header-anchor" href="#场景-5-sku-规格选择器" aria-label="Permalink to &quot;场景 5：SKU 规格选择器&quot;">​</a></h2><p><strong>业务背景</strong>：多规格商品需要在任意组合下正确置灰、回溯选中路径、计算价格区间与库存。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 每次点击全量重算可选性</td><td>遍历所有 SKU 判断</td><td>逻辑直观</td><td>O(n*m) 重复计算，长规格易卡顿</td></tr><tr><td>B. 预构建规格可达矩阵</td><td>初始化时构建邻接/可达表，点击只做局部回溯</td><td>点击 O(1) 级判断，易扩展</td><td>构建逻辑复杂，需要单测覆盖</td></tr></tbody></table><p><strong>选型：B。</strong> 实现位置：<code>components/business/SkuPopup.vue</code> + <code>composables/useSku.ts</code> + <code>utils/sku-matrix.ts</code>（阶段二）。验证：单测覆盖「选中 A 后 B 不可选」「取消 A 后 B 恢复」「无库存组合置灰」「价格区间计算」。</p><h2 id="场景-6-订单超时与倒计时" tabindex="-1">场景 6：订单超时与倒计时 <a class="header-anchor" href="#场景-6-订单超时与倒计时" aria-label="Permalink to &quot;场景 6：订单超时与倒计时&quot;">​</a></h2><p><strong>业务背景</strong>：待支付订单 15/30 分钟关闭；本地时间可被修改，页面隐藏后计时会漂移。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 直接 <code>Date.now()</code> 倒计时</td><td>页面内 <code>setInterval</code></td><td>实现快</td><td>本地时钟不准、后台挂起后错乱</td></tr><tr><td>B. 服务端校准 + 页面恢复重算</td><td>记录 <code>serverTimeOffset</code>，<code>onShow</code> 用服务端时间重算，归零自动刷新订单</td><td>准确、可恢复</td><td>需要统一时间工具与生命周期处理</td></tr></tbody></table><p><strong>选型：B。</strong> 实现位置：<code>utils/time.ts</code>、<code>components/business/CountDown.vue</code>、<code>stores/order.ts</code>。验证：手动改系统时间倒计时不变；切后台 5 分钟后回前台时间正确；归零自动请求订单状态。</p><h2 id="场景-7-支付结果确认" tabindex="-1">场景 7：支付结果确认 <a class="header-anchor" href="#场景-7-支付结果确认" aria-label="Permalink to &quot;场景 7：支付结果确认&quot;">​</a></h2><p><strong>业务背景</strong>：支付回跳不可靠，存在「已支付但订单状态未同步」；重复点击支付还会重复下单。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 仅依赖支付回调/回跳</td><td>回跳后直接展示成功</td><td>简单</td><td>回跳丢失、状态延迟时误判</td></tr><tr><td>B. 回跳 + 主动查询 + 轮询退避</td><td>先查一次，<code>PENDING</code> 时按 1s/2s/4s 退避轮询，超时给人工入口</td><td>结果可靠、可观测</td><td>需要轮询管理、幂等与取消</td></tr></tbody></table><p><strong>选型：B。</strong> 支付按钮加防重锁；<code>PaymentProvider</code> 内部封装各端差异；查询与轮询统一走 <code>stores/payment.ts</code>。验证：Mock 配置「支付成功但回调延迟 3s」仍能确认成功；连续点击支付只产生一笔支付单；取消支付回到待支付态。</p><h2 id="场景-8-schema-驱动表单" tabindex="-1">场景 8：Schema 驱动表单 <a class="header-anchor" href="#场景-8-schema-驱动表单" aria-label="Permalink to &quot;场景 8：Schema 驱动表单&quot;">​</a></h2><p><strong>业务背景</strong>：地址新增/编辑字段多、联动显隐、动态校验；后续售后申请、发票信息也要复用。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 每个表单手写模板与校验</td><td>页面内写死字段与规则</td><td>直接</td><td>重复代码、校验口径不一致</td></tr><tr><td>B. Schema 配置 → 渲染 + 校验</td><td><code>FormSchema</code> 组件读取字段配置、规则与联动</td><td>复用高、易测试</td><td>需要设计 schema 结构与渲染器</td></tr></tbody></table><p><strong>选型：B。</strong> 实现位置：<code>components/common/FormSchema.vue</code>、<code>utils/form-schema.ts</code>。验证：地址表单必填/手机号/邮编校验；选择「其他标签」时出现自定义输入；编辑态正确回填。</p><h2 id="场景-9-图片上传-售后凭证-头像" tabindex="-1">场景 9：图片上传（售后凭证/头像） <a class="header-anchor" href="#场景-9-图片上传-售后凭证-头像" aria-label="Permalink to &quot;场景 9：图片上传（售后凭证/头像）&quot;">​</a></h2><p><strong>业务背景</strong>：售后上传凭证需要压缩、限并发、失败重试、进度反馈，弱网下不能整批失败。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 直传原图，串行</td><td>选图后逐张上传</td><td>简单</td><td>大图慢、流量浪费、失败即中断</td></tr><tr><td>B. 压缩 + 并发上限 + 单张重试</td><td><code>uni.compressImage</code>，并发 3，失败指数退避，展示进度</td><td>体验稳、可恢复</td><td>需处理各端压缩能力差异</td></tr></tbody></table><p><strong>选型：B，已落地。</strong> 实现位置：<code>platform/upload.ts</code>（选图 / 压缩 / 上传，Mock 与真实切换）、<code>composables/useUpload.ts</code>（并发 3、自动重试 1 次、单张手动重试、上限 9）、<code>pages-sub/order/after-sale/index.vue</code>（凭证上传 UI 与提交拦截）。验证：<code>upload.spec.ts</code> 覆盖并发上限与重试；H5 售后页实测可新增凭证、进度展示、失败重试与删除。</p><h2 id="场景-10-拼团状态机" tabindex="-1">场景 10：拼团状态机 <a class="header-anchor" href="#场景-10-拼团状态机" aria-label="Permalink to &quot;场景 10：拼团状态机&quot;">​</a></h2><p><strong>业务背景</strong>：团单经历「待成团 → 成团 → 超时退款」，并发参团、满员、超时都要有确定 UI 与错误码。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 页面内 if/else 判断状态</td><td>各页面自行拼装文案</td><td>起步快</td><td>状态爆炸、分支遗漏、无法复用</td></tr><tr><td>B. 显式状态机 + store 推进</td><td>定义状态/事件/副作用表，定时器推进成团与退款</td><td>可穷举、可测试</td><td>需要状态机建模与定时器治理</td></tr></tbody></table><p><strong>选型：B。</strong> 实现位置：<code>stores/marketing/group.ts</code>、<code>mock/handlers/group.ts</code>（阶段四）。验证：2 人团在 1 人时展示「还差 1 人」；第 2 人加入立即成团；超时自动进入退款并刷新 UI；满员参团返回 <code>GROUP_FULL</code>。</p><h2 id="场景-11-秒杀状态机与轮询" tabindex="-1">场景 11：秒杀状态机与轮询 <a class="header-anchor" href="#场景-11-秒杀状态机与轮询" aria-label="Permalink to &quot;场景 11：秒杀状态机与轮询&quot;">​</a></h2><p><strong>业务背景</strong>：秒杀有「未开始 / 排队中 / 成功 / 售罄 / 失败」五态，必须处理排队 token、结果轮询、退避和防重复提交。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. 点击后等待接口返回</td><td>单次请求 + 按钮文案</td><td>简单</td><td>长排队会超时、无法表达中间态</td></tr><tr><td>B. 五态状态机 + token 轮询退避</td><td>排队拿 token，按 1s→2s→4s（上限 8s）轮询，终态停止</td><td>状态清晰、可回滚</td><td>需要轮询生命周期与页面隐藏处理</td></tr></tbody></table><p><strong>选型：B。</strong> 实现位置：<code>stores/marketing/seckill.ts</code>、<code>mock/handlers/seckill.ts</code>（阶段四）。验证：活动未开始按钮置灰并倒计时；排队中展示进度；成功后跳订单；售罄展示「已抢光」；页面隐藏停止轮询、回前台恢复。</p><h2 id="场景-12-权限与曝光埋点" tabindex="-1">场景 12：权限与曝光埋点 <a class="header-anchor" href="#场景-12-权限与曝光埋点" aria-label="Permalink to &quot;场景 12：权限与曝光埋点&quot;">​</a></h2><p><strong>业务背景</strong>：曝光埋点若在 <code>mounted</code> 触发，会把未进入视口的商品也计入；权限（相册/通知）需要统一判断。</p><table tabindex="0"><thead><tr><th>方案</th><th>做法</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>A. <code>mounted</code> 即上报</td><td>页面加载后批量上报</td><td>实现简单</td><td>数据失真，无法归因真实曝光</td></tr><tr><td>B. 可见性触发 + 统一权限入口</td><td><code>createIntersectionObserver</code> / 页面可见性，去重后上报；权限统一封装</td><td>数据可信、可归因</td><td>需要曝光去重与观察器生命周期管理</td></tr></tbody></table><p><strong>选型：B，已落地。</strong> 实现位置：<code>composables/useExposure.ts</code>（观察器生命周期 + 可见上报）、<code>utils/track.ts</code>（<code>dedupeKey</code> 会话去重、20 条批量上报、失败写入本地队列并按指数退避重发、启动补发）、<code>platform/permission.ts</code>（<code>getSetting</code> → <code>authorize</code> → <code>openSetting</code> 引导）、<code>pages/index/index.vue</code>（首页瀑布流曝光接入）。验证：<code>exposure.spec.ts</code> 覆盖同 id 去重与重复 observe，<code>track.spec.ts</code> 覆盖失败保留、自动重发与重启恢复；H5 首页快速滑动只上报进入视口的商品；相册权限拒绝后弹出「去设置」引导。</p><hr><h2 id="高阶组件清单-阶段二-四落地" tabindex="-1">高阶组件清单（阶段二～四落地） <a class="header-anchor" href="#高阶组件清单-阶段二-四落地" aria-label="Permalink to &quot;高阶组件清单（阶段二～四落地）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>核心 props</th><th>核心 emit</th><th>解决的问题</th></tr></thead><tbody><tr><td><code>SkuPopup</code></td><td><code>goods</code>、<code>visible</code>、<code>mode</code>（cart/buy）</td><td><code>confirm</code>、<code>close</code></td><td>规格矩阵、库存联动、加购/立即购买</td></tr><tr><td><code>VirtualList</code></td><td><code>list</code>、<code>itemHeight</code>、<code>height</code>、<code>dynamic</code></td><td><code>scroll</code>、<code>loadMore</code></td><td>1000+ 长列表滚动性能</td></tr><tr><td><code>WaterfallFlow</code></td><td><code>list</code>、<code>columns</code>、<code>gap</code></td><td><code>itemClick</code></td><td>双列瀑布流、占位防跳动</td></tr><tr><td><code>PopupManager</code></td><td><code>zIndexBase</code>、<code>lockScroll</code></td><td><code>open</code>、<code>close</code></td><td>多弹层叠加、返回键、滚动锁定</td></tr><tr><td><code>NavBar</code></td><td><code>title</code>、<code>transparent</code>、<code>showBack</code></td><td><code>back</code>、<code>heightChange</code></td><td>状态栏/胶囊/安全区适配</td></tr><tr><td><code>CountDown</code></td><td><code>endAt</code>、<code>serverTimeOffset</code></td><td><code>finish</code>、<code>tick</code></td><td>服务端校准、后台恢复</td></tr><tr><td><code>CanvasPoster</code></td><td><code>template</code>、<code>data</code></td><td><code>success</code>、<code>fail</code></td><td>分享海报生成与保存</td></tr><tr><td><code>FormSchema</code></td><td><code>schema</code>、<code>modelValue</code></td><td><code>update:modelValue</code>、<code>submit</code></td><td>配置化表单</td></tr><tr><td><code>LiveProductBar</code></td><td><code>products</code>、<code>currentId</code></td><td><code>buy</code>、<code>switch</code></td><td>直播间讲解商品联动</td></tr><tr><td><code>SeckillBar</code></td><td><code>activity</code>、<code>state</code></td><td><code>buy</code></td><td>秒杀价条、库存进度、三态按钮</td></tr></tbody></table><p>每个组件在实现阶段补充独立说明（props / emit / slot / 使用示例）。</p>',54)])])}const u=d(c,[["render",a]]);export{b as __pageData,u as default};
